//! Wolfram exact-system replay for iterative Krylov solvers.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `wolfram/iterative_golden.wls` under Wolfram Engine 15.0.0) carries two
//! small exact systems with known spectra, per
//! audit-sonium-solvers-iterative-20260921: a nonnormal real 3x3 companion
//! matrix with integer spectrum {1, 2, 3} and a complex Hermitian indefinite
//! 2x2 MINRES model problem. The replay checks exact solution error together
//! with the independently recomputed residual and backward error (an
//! ill-conditioned system can report a small residual with a large solution
//! error), plus an adjoint identity on the nonsymmetric system.

use num_complex::Complex64;
use serde::Deserialize;
use sonium_solvers_core::traits::LinearOperator;
use sonium_solvers_iterative::{GmresConfig, MinresConfig, gmres, minres};
use sonium_solvers_sparse::CsrMatrix;

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Meta {
    engine: String,
    protocol: String,
}

#[derive(Debug, Deserialize)]
struct RealSystem {
    a: Vec<Vec<String>>,
    eigenvalues_exact: Vec<String>,
    x1: Vec<String>,
    b1: Vec<String>,
    x2: Vec<String>,
    b2: Vec<String>,
    adjoint_probe_y: Vec<String>,
    transpose_y: Vec<String>,
}

#[derive(Debug, Deserialize, Clone)]
struct ComplexDecimal {
    re: String,
    im: String,
}

#[derive(Debug, Deserialize)]
struct ComplexSystem {
    a: Vec<Vec<ComplexDecimal>>,
    eigenvalues_exact: Vec<String>,
    eigenvalues_num: Vec<ComplexDecimal>,
    x: Vec<ComplexDecimal>,
    b: Vec<ComplexDecimal>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    meta: Meta,
    nonsym_companion_3x3: RealSystem,
    hermitian_indefinite_2x2: ComplexSystem,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_complex(value: &ComplexDecimal) -> Complex64 {
    Complex64::new(parse(&value.re), parse(&value.im))
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Wolfram iterative fixture");
    assert!(
        fixture.meta.engine.contains("Wolfram Engine"),
        "fixture must record its Wolfram provenance"
    );
    assert_eq!(fixture.meta.protocol, "audit-oracle-hermetic-v1");
    fixture
}

fn real_csr(entries: &[Vec<String>]) -> CsrMatrix<f64> {
    let triplets = entries
        .iter()
        .enumerate()
        .flat_map(|(i, row)| {
            row.iter()
                .enumerate()
                .map(move |(j, value)| (i, j, parse(value)))
        })
        .collect();
    let n = entries.len();
    CsrMatrix::from_triplets(n, n, triplets)
}

fn complex_csr(entries: &[Vec<ComplexDecimal>]) -> CsrMatrix<Complex64> {
    let triplets = entries
        .iter()
        .enumerate()
        .flat_map(|(i, row)| {
            row.iter()
                .enumerate()
                .map(move |(j, value)| (i, j, parse_complex(value)))
        })
        .collect();
    let n = entries.len();
    CsrMatrix::from_triplets(n, n, triplets)
}

fn norm(values: &[f64]) -> f64 {
    values.iter().map(|v| v * v).sum::<f64>().sqrt()
}

fn complex_norm(values: &[Complex64]) -> f64 {
    values.iter().map(|v| v.norm_sqr()).sum::<f64>().sqrt()
}

fn gmres_config() -> GmresConfig<f64> {
    GmresConfig {
        max_iterations: 10,
        restart: 3,
        tolerance: 1e-12,
        ..Default::default()
    }
}

#[test]
fn gmres_nonsymmetric_matches_wolfram_exact_solutions() {
    let fixture = parse_fixture();
    let system = &fixture.nonsym_companion_3x3;
    // The oracle spectrum is exact: companion of (x-1)(x-2)(x-3).
    let mut spectrum: Vec<i64> = system
        .eigenvalues_exact
        .iter()
        .map(|value| value.parse().expect("exact integer eigenvalue"))
        .collect();
    spectrum.sort_unstable();
    assert_eq!(spectrum, vec![1, 2, 3]);

    let matrix = real_csr(&system.a);
    for (x_key, b_key) in [(&system.x1, &system.b1), (&system.x2, &system.b2)] {
        let exact: Vec<f64> = x_key.iter().map(|value| parse(value)).collect();
        let rhs: Vec<f64> = b_key.iter().map(|value| parse(value)).collect();
        let solution = gmres(&matrix, &rhs, &gmres_config());
        assert!(solution.converged, "GMRES must converge on 3x3 {x_key:?}");
        // Exact solution error together with residual and backward error:
        // a small residual alone cannot certify a nonnormal solve.
        let error: Vec<f64> = solution
            .x
            .iter()
            .zip(&exact)
            .map(|(got, want)| got - want)
            .collect();
        let scale = norm(&exact).max(1.0);
        assert!(
            norm(&error) <= 1e-9 * scale,
            "solution error {} exceeds budget",
            norm(&error)
        );
        assert!(
            solution.residual <= 1e-10,
            "true residual {} exceeds budget",
            solution.residual
        );
        assert!(
            solution.backward_error <= 1e-10,
            "backward error {} exceeds budget",
            solution.backward_error
        );
    }
}

#[test]
fn adjoint_identity_matches_wolfram_transpose_action() {
    let fixture = parse_fixture();
    let system = &fixture.nonsym_companion_3x3;
    let matrix = real_csr(&system.a);
    let y: Vec<f64> = system
        .adjoint_probe_y
        .iter()
        .map(|value| parse(value))
        .collect();
    let expected: Vec<f64> = system
        .transpose_y
        .iter()
        .map(|value| parse(value))
        .collect();
    let actual = matrix.apply_transpose(&y);
    assert_eq!(actual.len(), expected.len());
    for (index, (got, want)) in actual.iter().zip(expected.iter()).enumerate() {
        assert!(
            (got - want).abs() <= 1e-12 * want.abs().max(1.0),
            "transpose_y[{index}]: {got:e} != {want:e}"
        );
    }
    // Adjoint identity <A^Ty, x> == <y, Ax> on the oracle pair.
    let x: Vec<f64> = system.x1.iter().map(|value| parse(value)).collect();
    let ax = matrix.apply(&x);
    let left: f64 = actual.iter().zip(&x).map(|(a, b)| a * b).sum();
    let right: f64 = y.iter().zip(&ax).map(|(a, b)| a * b).sum();
    assert!(
        (left - right).abs() <= 1e-12 * left.abs().max(1.0),
        "adjoint identity drifted: {left:e} != {right:e}"
    );
}

#[test]
fn minres_hermitian_indefinite_matches_wolfram_exact() {
    let fixture = parse_fixture();
    let system = &fixture.hermitian_indefinite_2x2;
    // The oracle spectrum straddles zero: the model indefinite problem.
    // Both the symbolic exact forms and the numeric values are pinned.
    assert_eq!(system.eigenvalues_exact.len(), 2);
    assert!(
        system.eigenvalues_exact[0].contains("Sqrt(17)")
            && system.eigenvalues_exact[1].contains("Sqrt(17)"),
        "oracle must record the closed-form indefinite spectrum"
    );
    let eigenvalues: Vec<f64> = system
        .eigenvalues_num
        .iter()
        .map(|value| parse(&value.re))
        .collect();
    assert_eq!(eigenvalues.len(), 2);
    assert!(
        eigenvalues[0] < 0.0 && eigenvalues[1] > 0.0,
        "fixture spectrum must be indefinite: {eigenvalues:?}"
    );

    let matrix = complex_csr(&system.a);
    let exact: Vec<Complex64> = system.x.iter().map(parse_complex).collect();
    let rhs: Vec<Complex64> = system.b.iter().map(parse_complex).collect();
    let config = MinresConfig {
        max_iterations: 10,
        tolerance: 1e-12,
        ..Default::default()
    };
    let solution = minres(&matrix, &rhs, &config);
    let error: Vec<Complex64> = solution
        .x
        .iter()
        .zip(&exact)
        .map(|(got, want)| got - want)
        .collect();
    let scale = complex_norm(&exact).max(1.0);
    assert!(
        complex_norm(&error) <= 1e-9 * scale,
        "MINRES solution error {} exceeds budget",
        complex_norm(&error)
    );
    assert!(
        solution.residual <= 1e-10,
        "MINRES true residual {} exceeds budget",
        solution.residual
    );
    assert!(
        solution.backward_error <= 1e-10,
        "MINRES backward error {} exceeds budget",
        solution.backward_error
    );
}
